CREATE TYPE "evidence_review_state" AS ENUM ('unreviewed', 'reviewed', 'verified');
CREATE TYPE "evidence_kind" AS ENUM ('certification', 'cv', 'portfolio', 'project_example', 'supporting_document');
CREATE TYPE "note_visibility" AS ENUM ('private_to_author', 'shared_upward');
CREATE TABLE "designations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL UNIQUE, "sort_order" integer NOT NULL DEFAULT 0, "active" boolean NOT NULL DEFAULT true, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "skills" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL UNIQUE, "active" boolean NOT NULL DEFAULT true, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "arrangement_labels" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL UNIQUE, "color" text NOT NULL, "sort_order" integer NOT NULL DEFAULT 0, "active" boolean NOT NULL DEFAULT true, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "employee_profiles" ("user_id" text PRIMARY KEY REFERENCES "users"("id") ON DELETE RESTRICT, "employee_code" text NOT NULL UNIQUE, "work_email" text, "work_phone" text, "professional_summary" text, "designation_id" uuid REFERENCES "designations"("id") ON DELETE RESTRICT, "team" text, "manager_user_id" text REFERENCES "users"("id") ON DELETE RESTRICT, "default_work_location" text, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "employee_skills" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "employee_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "skill_id" uuid NOT NULL REFERENCES "skills"("id") ON DELETE RESTRICT, "proficiency_description" text, "experience_description" text, "notes" text, "coverage_eligible" boolean, "verified" boolean NOT NULL DEFAULT false, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("employee_user_id", "skill_id"));
CREATE TABLE "employee_evidence" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "uploader_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "kind" "evidence_kind" NOT NULL, "title" text NOT NULL, "issuer" text, "issue_date" date, "expiry_date" date, "related_skill_id" uuid REFERENCES "skills"("id") ON DELETE RESTRICT, "external_url" text, "review_state" "evidence_review_state" NOT NULL DEFAULT 'unreviewed', "reviewed_by_user_id" text REFERENCES "users"("id") ON DELETE RESTRICT, "reviewed_at" timestamptz, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CHECK ("expiry_date" IS NULL OR "issue_date" IS NULL OR "expiry_date" >= "issue_date"));
CREATE TABLE "employee_files" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "evidence_id" uuid NOT NULL REFERENCES "employee_evidence"("id") ON DELETE RESTRICT, "owner_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "storage_key" text NOT NULL UNIQUE, "original_filename" text NOT NULL, "content_type" text NOT NULL, "size_bytes" integer NOT NULL CHECK ("size_bytes" > 0), "archived_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "employee_management_notes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "subject_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "author_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "author_role" "system_role" NOT NULL, "visibility" "note_visibility" NOT NULL, "content" text NOT NULL, "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "employee_profiles_team_idx" ON "employee_profiles"("team");
CREATE INDEX "employee_skills_employee_idx" ON "employee_skills"("employee_user_id");
CREATE INDEX "employee_evidence_owner_idx" ON "employee_evidence"("owner_user_id", "archived_at");
CREATE INDEX "employee_files_evidence_idx" ON "employee_files"("evidence_id");
CREATE INDEX "employee_management_notes_subject_idx" ON "employee_management_notes"("subject_user_id", "archived_at");
